def get_parameters(
    vault: SmartContractVault, param_fetcher_id: str = LATE_PAYMENT_FEE_POF_ID
) -> dict[str, datetime | Decimal | str | None]:
    """Retrieves configuration parameters for the late payment fee feature.

    Args:
        vault: The SmartContractVault instance to query.
        param_fetcher_id: The unique identifier for the parameter fetcher.

    Returns:
        Parameters for the late payment fee feature.
    """
    return vault.get_parameters_observation(fetcher_id=param_fetcher_id).parameters


def _append_to_state(
    state: state_utils.SmartContractState,
    balance_fetcher_id: str = common_fetchers.EFFECTIVE_DATE_BOF_ID,
    param_fetcher_id: str = LATE_PAYMENT_FEE_POF_ID,
) -> state_utils.SmartContractState:
    """Updates the contract state with live balances and specific parameter observations."""
    return state_utils.append_to_state(
        state=state,
        parameters=get_parameters(state.vault, param_fetcher_id),
        balances=state.vault.get_balances_observation(fetcher_id=balance_fetcher_id).balances,
    )


def _get_balance_at_address(balances: Mapping, address: str, denomination: str) -> Decimal:
    """Gets the net balance at a specific address."""
    return balances[(address, DEFAULT_ASSET, denomination, Phase.COMMITTED)].net


def get_scheduled_events(
    state: state_utils.SmartContractState,
    fetchers_config: LatePaymentFeeFetchersConfig = DEFAULT_LATE_PAYMENT_FEE_FETCHERS_CONFIG,
) -> dict[str, ScheduledEvent]:
    """Get scheduled event for the late payment check.

    The check runs monthly on the configured day (typically statement_day + payment_due_days).

    Args:
        state: The current state of the smart contract.
        fetchers_config: Configuration for the fetchers.

    Returns:
        The scheduled events for the late payment check.
    """
    state = state_utils.append_to_state(
        state=state,
        parameters=get_parameters(state.vault, fetchers_config.param_fetcher_id),
    )

    schedule_param_ids = {
        LATE_PAYMENT_CHECK_DAY_PARAM.id,
        LATE_PAYMENT_CHECK_TIME_PARAM.id,
    }

    rejection = state_utils.check_parameters_exist(state=state, param_ids=schedule_param_ids)
    assert rejection is None, rejection

    check_time_str: str = state.parameters[LATE_PAYMENT_CHECK_TIME_PARAM.id]  # type: ignore
    check_time: date_and_time.Time = date_and_time.parse_time_str(check_time_str)

    day = int(state.parameters[LATE_PAYMENT_CHECK_DAY_PARAM.id])  # type: ignore

    return {
        CHECK_LATE_PAYMENT_EVENT: ScheduledEvent(
            start_datetime=state.effective_datetime.astimezone(state.vault.events_timezone),
            expression=ScheduleExpression(
                day=day,
                hour=check_time.hour,
                minute=check_time.minute,
                second=check_time.second,
            ),
        )
    }


def check_and_apply_late_payment_fee(
    state: state_utils.SmartContractState,
    account_type: str = "",
    fetchers_config: LatePaymentFeeFetchersConfig = DEFAULT_LATE_PAYMENT_FEE_FETCHERS_CONFIG,
) -> list[CustomInstruction]:
    """Checks if the minimum payment has been met and applies a late payment fee if not.

    Compares TOTAL_REPAYMENTS_TRACKER vs MINIMUM_PAYMENT_DUE_TRACKER.
    If repayments < minimum payment due, charges the late payment fee.

    Args:
        state: The current state of the smart contract.
        account_type: The account type for GL impact details.
        fetchers_config: Configuration for the fetchers.

    Returns:
        List of custom instructions for the late payment fee.
    """
    state = _append_to_state(state=state, param_fetcher_id=fetchers_config.param_fetcher_id)

    rejection = state_utils.check_parameters_exist(
        state=state,
        param_ids={
            fetchers_config.denomination_param_id,
            LATE_PAYMENT_FEE_AMOUNT_PARAM.id,
            LATE_PAYMENT_FEE_INCOME_ACCOUNT_PARAM.id,
            LATE_PAYMENT_FEE_ENABLED_PARAM.id,
        },
    )
    assert rejection is None, rejection

    if not common_utils.str_to_bool(str(state.parameters[LATE_PAYMENT_FEE_ENABLED_PARAM.id])):
        return []

    denomination: str = str(state.parameters[fetchers_config.denomination_param_id])
    fee_amount: Decimal = state.parameters[LATE_PAYMENT_FEE_AMOUNT_PARAM.id]  # type: ignore
    fee_income_account: str = state.parameters[LATE_PAYMENT_FEE_INCOME_ACCOUNT_PARAM.id]  # type: ignore

    if fee_amount <= 0:
        return []

    minimum_payment_due = _get_balance_at_address(
        state.balances, apex_addresses.MINIMUM_PAYMENT_DUE_TRACKER, denomination
    )
    total_repayments = _get_balance_at_address(
        state.balances, apex_addresses.TOTAL_REPAYMENTS_TRACKER, denomination
    )

    # No minimum payment due means no check needed
    if minimum_payment_due <= 0:
        return []

    # Payment shortfall
    if total_repayments < minimum_payment_due:
        return [
            CustomInstruction(
                postings=posting_utils.create_postings(
                    amount=fee_amount,
                    debit_account=state.vault.account_id,
                    debit_address=apex_addresses.FEES,
                    credit_account=fee_income_account,
                    denomination=denomination,
                ),
                value_datetime=state.effective_datetime,
                instruction_details=posting_utils.standard_instruction_details(
                    description=(
                        f"Late payment fee: {fee_amount}. "
                        f"Minimum due: {minimum_payment_due}, "
                        f"Paid: {total_repayments}."
                    ),
                    event_type=CHECK_LATE_PAYMENT_EVENT,
                    gl_impacted=True,
                    account_type=account_type,
                ),
                override_all_restrictions=True,
            )
        ]

    return []
